import React, { useState, useEffect } from "react";
import "./IncomeCategory.css";
import "./Questionnaire.css";

function BudgetLimits({ formData, updateData }) {
  // Only categories with priority >=3
  const categories = Object.keys(formData.spendingPriorities || {}).filter(
    cat => formData.spendingPriorities[cat] >= 3
  );

  const [limits, setLimits] = useState({});

  useEffect(() => {
    const initial = {};
    categories.forEach(cat => initial[cat] = "");
    setLimits(initial);
  }, [categories]);

  const handleChange = (cat, value) => {
    setLimits(prev => ({ ...prev, [cat]: value }));
  };

  const handleSave = () => {
    const filteredLimits = {};
    Object.keys(limits).forEach(cat => {
      if (limits[cat] !== "") filteredLimits[cat] = limits[cat];
    });

    if (Object.keys(filteredLimits).length === 0) {
      alert("Please set at least one budget limit");
      return;
    }

    updateData({ budgetLimits: filteredLimits });
    alert("Data saved successfully!");
  };

  if (!categories.length) {
    return <p style={{ textAlign: "center", color: "red" }}>
      No categories with priority ≥ 3. Please go back and select categories.
    </p>;
  }

  return (
    <div className="income-container">
      <h1 className="income-title">Set Monthly Budget Limits</h1>
      <p className="income-subtitle">
        Set your budget for each category with priority ≥ 3
      </p>

      <div className="income-grid">
        {categories.map(cat => (
          <div key={cat} className="income-card">
            <div className="income-name">{cat}</div>
            <input
              type="number"
              placeholder="Enter monthly budget"
              value={limits[cat]}
              onChange={e => handleChange(cat, e.target.value)}
              className="form-input"
            />
          </div>
        ))}
      </div>

      <button
        className="next-button"
        style={{ maxWidth: "300px" }}
        onClick={handleSave}
      >
        Save Budget
      </button>
    </div>
  );
}

export default BudgetLimits;
